//! Canonical fieldset identity and readonly form/type metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><fieldset id=fieldset name=group><legend>Group</legend><input value=seed></fieldset></form><form id=other></form><fieldset id=external form=other></fieldset></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://fieldset-metadata.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn fieldset_validation_non_candidate_native_getters(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('fieldset'),P=HTMLFieldSetElement.prototype,w=Object.getOwnPropertyDescriptor(P,'willValidate'),m=Object.getOwnPropertyDescriptor(P,'validationMessage');if(!w||!m||typeof w.get!=='function'||typeof m.get!=='function'||w.set!==undefined||m.set!==undefined)throw 'canonical readonly validation';if(x.willValidate!==false||x.validationMessage!==''||w.get.call(x)!==false||m.get.call(x)!=='')throw 'noncandidate metadata';x.disabled=true;x.name='group';if(x.willValidate!==false||x.validationMessage!==''||x.disabled!==true||x.name!=='group'||x.form!==document.getElementById('owner'))throw 'independent metadata';");}
#[test]
fn fieldset_validation_non_candidate_methods_no_events_or_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('fieldset'),P=HTMLFieldSetElement.prototype,count=0;x.addEventListener('invalid',function(){count++;});document.addEventListener('invalid',function(){count++;},true);if(typeof P.checkValidity!=='function'||typeof P.reportValidity!=='function'||P.checkValidity.length!==0||P.reportValidity.length!==0)throw 'canonical validation methods';var ignored={toString:function(){throw 'ignored argument';},valueOf:function(){throw 'ignored argument';}};if(x.checkValidity(ignored,Symbol())!==true||x.reportValidity(Symbol(),ignored)!==true||count)throw 'noncandidate methods';if(x.name!=='group'||x.disabled!==false||x.form!==document.getElementById('owner'))throw 'validation changed native state';");}
#[test]
fn fieldset_validation_non_candidate_inert_clone_and_adoption(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','fieldset');x.name='group';x.disabled=true;var clone=x.cloneNode(false),other=new Document();other.adoptNode(x);for(var node of [x,clone]){if(node.willValidate!==false||node.validationMessage!==''||node.checkValidity()!==true||node.reportValidity()!==true)throw 'inert noncandidate';if(node.name!=='group'||node.disabled!==true)throw 'inert metadata preserved';}if(x.ownerDocument!==other)throw 'adoption identity';");}

#[test]
fn fieldset_validation_descriptors_brands_readonly_and_ignored_arguments(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('fieldset'),proto=HTMLFieldSetElement.prototype,entries=[];for(var key of ['willValidate','validationMessage']){var a=Object.getOwnPropertyDescriptor(proto,key);if(!a.enumerable||!a.configurable||a.set!==undefined||a.get.name!=='get '+key||a.get.length!==0||Object.hasOwn(o,key))throw 'readonly descriptor';entries.push(a.get);o[key]='authored';var caught=false;try{(function(){'use strict';o[key]='authored';})();}catch(e){caught=e instanceof TypeError;}if(!caught||Object.hasOwn(o,key))throw 'readonly assignment';}for(var key of ['checkValidity','reportValidity']){var a=Object.getOwnPropertyDescriptor(proto,key);if(!a.enumerable||!a.configurable||!a.writable||a.value.name!==key||a.value.length!==0||Object.hasOwn(o,key))throw 'method descriptor';entries.push(a.value);}for(var bad of [null,undefined,{},Object.create(proto),document.createElement('input'),document.createElement('div'),document.createElementNS('urn:foreign','fieldset')]){for(var entry of entries){var caught=false;try{entry.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine validation brand';}}var ignored={toString:function(){throw 'ignored';},valueOf:function(){throw 'ignored';}};if(o.willValidate!==false||o.validationMessage!==''||o.checkValidity(ignored,Symbol())!==true||o.reportValidity(Symbol(),ignored)!==true)throw 'ignored arguments';"#);}
#[test]
fn fieldset_validation_author_shadows_delete_and_canonical_restore(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('fieldset'),proto=HTMLFieldSetElement.prototype;for(var key of ['willValidate','validationMessage','checkValidity','reportValidity']){var a=Object.getOwnPropertyDescriptor(proto,key),canonical=a.get||a.value,expected=key==='willValidate'?false:key==='validationMessage'?'':true;Object.defineProperty(o,key,{value:'own',writable:true,configurable:true});if(o[key]!=='own'||canonical.call(o)!==expected)throw 'own shadow';delete o[key];Object.defineProperty(proto,key,{value:'prototype',writable:true,configurable:true});if(o[key]!=='prototype'||canonical.call(o)!==expected)throw 'prototype shadow';delete proto[key];if(o[key]!==undefined||canonical.call(o)!==expected)throw 'deleted canonical entry';Object.defineProperty(proto,key,a);if(Object.hasOwn(o,key)||(a.get?o[key]:o[key]())!==expected)throw 'canonical restore';}var count=0;for(var key in o)if(key==='willValidate'||key==='validationMessage'||key==='checkValidity'||key==='reportValidity')count++;if(count!==4)throw 'canonical enumeration';"#);}
#[test]
fn fieldset_validation_saved_child_origin_refuses_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('fieldset'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var proto=frame.contentWindow.HTMLFieldSetElement.prototype,w=Object.getOwnPropertyDescriptor(proto,'willValidate').get,m=Object.getOwnPropertyDescriptor(proto,'validationMessage').get,c=proto.checkValidity,r=proto.reportValidity;if(w.call(o)!==false||m.call(o)!==''||c.call(o)!==true||r.call(o)!==true)throw 'saved child validation';"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://foreign-output-validation.test/",&crate::navigation::Location::home()).unwrap());for source in ["w.call(o);","m.call(o);","c.call(o);","r.call(o);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://fieldset-metadata.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(w.call(o)!==false||m.call(o)!==''||c.call(o)!==true||r.call(o)!==true)throw 'saved validation recovery';");}
#[test]
fn fieldset_validation_native_work_deadline_refusal_and_no_storage_requirements(){for method in [script_fieldset_validation::WILL_GET,script_fieldset_validation::MESSAGE_GET,script_fieldset_validation::CHECK,script_fieldset_validation::REPORT]{for expired in [false,true]{let(mut d,mut f,mut p)=fixture();let n=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()=="fieldset")).unwrap();let object=node_handle(n);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.attributes.len());p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.fieldset_validation(object,method).unwrap_err();assert!(e.contains("work")||e.contains("time"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.attributes.len()),state);p.begin_job();p.state.execution_deadline=None;p.state.retained_limit=p.state.retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.fieldset_validation(object,method).unwrap();match method{script_fieldset_validation::WILL_GET=>assert!(matches!(value,Value::Bool(false))),script_fieldset_validation::MESSAGE_GET=>assert!(matches!(value,Value::String(ref s)if s.is_empty())),_=>assert!(matches!(value,Value::Bool(true)))}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.attributes.len()),state);}}}
